Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_next_when_current_equals_len(void) {
    Vector* vec = helper_create_vector(0);
    TEST_ASSERT_NOT_NULL(vec);
    if (vec == NULL) return;

    int values[] = {10, 20, 30};
    int ret = helper_fill_vector(vec, values, 3);
    if (ret == -1) {
        helper_cleanup_vector(vec);
        return;
    }
    TEST_ASSERT_EQUAL_INT(0, ret);

    vec->current = 3;
    TEST_ASSERT_EQUAL_INT(3, vec->current);
    TEST_ASSERT_EQUAL_INT(3, vec->len);

    int result = next(vec);
    TEST_ASSERT_EQUAL_INT(10, result);
    TEST_ASSERT_EQUAL_INT(1, vec->current);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_next_when_current_equals_len);
    return UNITY_END();
}

